// ── framer/shared/month.ts ──────────────────────────────────────────────────

// month.ts — the logic behind the public calendar: which month, which days, which
// classes on each day, the phone's list of upcoming classes, places left and the
// waiting-list link, and each class's shade of the site's colour.
//
// No screen and no network here, so the tests can load it directly.
// Every date and time is worked out in the calendar's timezone, never the visitor's.

interface CalendarSession {    // one class, as the website reads it from Supabase
  id: string
  title: string
  starts_at: string
  ends_at: string
  location: string | null
  details: Record<string, string>
  places_left: number | null          // null = no limit
}

type DayKey = string           // a date in the calendar's timezone, like "2026-09-28"

interface PlacedSession extends CalendarSession {
  day: DayKey                         // its date on the calendar's clock
  time: string                        // start time on the calendar's clock, like "4:30 PM"
  past: boolean                       // started already, so greyed out
}

interface Day {
  key: DayKey
  date: number                        // day of the month
  inMonth: boolean                    // false for the grid's days before the 1st or after the last: left blank
  isToday: boolean
  isPast: boolean                     // the whole day is over, so greyed out
  sessions: PlacedSession[]           // in time order
}

interface Month {
  year: number
  month: number                       // 1 = January … 12 = December
  weekdays: number[]                  // the columns: 0 = Monday … 6 = Sunday
  weeks: Day[][]                      // the rows, one Day per column
}

// ------------------------------------------------------------------
//  Dates and times in the calendar's timezone
// ------------------------------------------------------------------

const formats = new Map<string, Intl.DateTimeFormat>()

// The calendar's date and clock at a moment: { day: "2026-09-30", hour: 16, minute: "30" }
function clock(moment: Date, timeZone: string) {
  if (!formats.has(timeZone)) {
    formats.set(timeZone, new Intl.DateTimeFormat("en-GB", {
      timeZone, year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit", hourCycle: "h23",
    }))
  }
  const parts: Record<string, string> = {}
  for (const p of formats.get(timeZone)!.formatToParts(moment)) parts[p.type] = p.value
  return { day: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: parts.minute }
}

function calendarDay(moment: Date, timeZone: string): DayKey {
  return clock(moment, timeZone).day
}

// A moment's time on the calendar's clock: timeOf(moment, "Asia/Beirut") is "4:30 PM".
function timeOf(moment: Date, timeZone: string): string {
  const { hour, minute } = clock(moment, timeZone)
  return formatTime(hour, minute)
}

// The 12-hour clock: formatTime(16, "30") is "4:30 PM", formatTime(0, "15") is "12:15 AM".
function formatTime(hour: number, minute: string): string {
  return `${hour % 12 || 12}:${minute} ${hour < 12 ? "AM" : "PM"}`
}

// Counting days on dates alone, with no clock involved, so a clock change
// (Lebanon's happen at midnight) can never shift the answer.
function addDays(day: DayKey, n: number): DayKey {
  const [y, m, d] = day.split("-").map(Number)
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10)
}

function weekdayOf(day: DayKey): number {   // 0 = Monday … 6 = Sunday
  const [y, m, d] = day.split("-").map(Number)
  return (new Date(Date.UTC(y, m - 1, d)).getUTCDay() + 6) % 7
}

// Today, and the first and last day of the month we're in.
function monthOf(now: Date, timeZone: string) {
  const today = calendarDay(now, timeZone)
  const [year, month] = today.split("-").map(Number)
  const first = `${today.slice(0, 7)}-01`
  const last = new Date(Date.UTC(year, month, 0)).toISOString().slice(0, 10)   // day 0 of next month
  return { today, year, month, first, last }
}

// What to ask Supabase for: the whole month (the grid) and the next 30 days (the phone
// list), plus a day on each side, because the calendar's midnight isn't UTC's.
// buildMonth() and upcoming() then keep exactly the right days.
function fetchRange(now: Date, timeZone: string): { from: DayKey; to: DayKey } {
  const { today, first, last } = monthOf(now, timeZone)
  const listEnd = addDays(today, LIST_DAYS)
  return { from: addDays(first, -1), to: addDays(listEnd > last ? listEnd : last, 2) }
}

// A session with its day, time and state worked out on the calendar's clock.
function place(s: CalendarSession, now: Date, timeZone: string): PlacedSession {
  const start = new Date(s.starts_at)
  const { day, hour, minute } = clock(start, timeZone)
  return { ...s, day, time: formatTime(hour, minute), past: start.getTime() <= now.getTime() }   // greyed from the moment it starts
}

const byStart = (a: PlacedSession, b: PlacedSession) =>
  Date.parse(a.starts_at) - Date.parse(b.starts_at) || a.title.localeCompare(b.title)

// ------------------------------------------------------------------
//  The grid
// ------------------------------------------------------------------

// The month as rows of weeks, Monday to Sunday, with the days before the 1st and after
// the last left blank. `days` is the client's setting (0 = Monday … 6 = Sunday); a day
// that is switched off still gets its column if it has a class this month, so a one-off
// Sunday workshop can't be invisible.
function buildMonth(
  sessions: CalendarSession[],
  { now, timeZone, days }: { now: Date; timeZone: string; days: number[] },
): Month {
  const { today, year, month, first, last } = monthOf(now, timeZone)

  // Every day from the Monday before the 1st to the Sunday after the last.
  const grid: Day[] = []
  const end = addDays(last, 6 - weekdayOf(last))
  for (let key = addDays(first, -weekdayOf(first)); key <= end; key = addDays(key, 1)) {
    const inMonth = key >= first && key <= last
    grid.push({ key, date: Number(key.slice(8)), inMonth, isToday: key === today, isPast: key < today, sessions: [] })
  }

  for (const s of sessions) {
    const placed = place(s, now, timeZone)
    const cell = grid.find((d) => d.key === placed.day && d.inMonth)
    if (cell) cell.sessions.push(placed)                   // else it belongs to another month
  }
  for (const d of grid) d.sessions.sort(byStart)

  // Columns: the chosen days, plus any day of the week that has a class this month.
  const weekdays = [0, 1, 2, 3, 4, 5, 6].filter((w) =>
    days.includes(w) || grid.some((d, i) => i % 7 === w && d.sessions.length > 0))

  // Rows: one per week, keeping only those columns. A row with no day of this month is dropped.
  const weeks: Day[][] = []
  for (let i = 0; i < grid.length; i += 7) {
    const row = weekdays.map((w) => grid[i + w])
    if (row.some((d) => d.inMonth)) weeks.push(row)
  }

  return { year, month, weekdays, weeks }
}

// ------------------------------------------------------------------
//  The phone list
// ------------------------------------------------------------------

const LIST_DAYS = 30          // the phone list runs from today to 30 days ahead

// The phone view: classes that haven't started yet, from now to 30 days ahead, in time
// order, whatever month they're in. Full classes stay in; the page marks them.
function upcoming(sessions: CalendarSession[], { now, timeZone }: { now: Date; timeZone: string }): PlacedSession[] {
  const lastDay = addDays(calendarDay(now, timeZone), LIST_DAYS)
  return sessions
    .map((s) => place(s, now, timeZone))
    .filter((s) => !s.past && s.day <= lastDay)
    .sort(byStart)
}

// ------------------------------------------------------------------
//  Places left and the waiting list
// ------------------------------------------------------------------

// What a class shows about its places: "full", the number when only a few are left, or
// nothing. `showFrom` is the client's setting: 3 shows "3 places left" and fewer; 0 never
// shows a number, only "full".
function placesNote(placesLeft: number | null, showFrom: number): "full" | number | null {
  if (placesLeft === null) return null                  // no limit
  if (placesLeft <= 0) return "full"
  return placesLeft <= showFrom ? placesLeft : null
}

// Puts values into the client's wording: fillIn("See you {day}", { day: "Wed" }) is
// "See you Wed". A name with no value is left as it is.
function fillIn(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (whole, name: string) => values[name] ?? whole)
}

// A link that opens WhatsApp with the message ready to send; null when no number is set.
function whatsappLink(number: string, message: string): string | null {
  const digits = number.replace(/\D/g, "")
  return digits ? `https://wa.me/${digits}?text=${encodeURIComponent(message)}` : null
}

// ------------------------------------------------------------------
//  Names, in the site's language
// ------------------------------------------------------------------

// A row's date in the phone list: "Tue, Sep 29" in English, "mar. 29 sept." in French.
function dayLabel(day: DayKey, language: string): string {
  const [y, m, d] = day.split("-").map(Number)
  return new Intl.DateTimeFormat(language, { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" })
    .format(Date.UTC(y, m - 1, d))
}

// Short day names, Monday first: ["Mon", "Tue", …] in English, ["lun.", "mar.", …] in French.
function weekdayNames(language: string): string[] {
  const format = new Intl.DateTimeFormat(language, { weekday: "short", timeZone: "UTC" })
  return [0, 1, 2, 3, 4, 5, 6].map((i) => format.format(Date.UTC(2026, 8, 28 + i)))   // 28 Sep 2026 was a Monday
}

// The month's title: "September 2026", or "septembre 2026" in French.
function monthTitle(year: number, month: number, language: string): string {
  return new Intl.DateTimeFormat(language, { month: "long", year: "numeric", timeZone: "UTC" })
    .format(Date.UTC(year, month - 1, 1))
}

// ------------------------------------------------------------------
//  Colour: each class name gets a tint of the site's main colour
// ------------------------------------------------------------------

const SHADES = 5              // how many tints; with more class names than this, some share
const LIGHTEST = 0.12         // how much of the main colour is in the lightest tint (the rest is white)
const DEEPEST = 0.55          // ...and in the deepest, unless that would make text hard to read
const MIN_LUMINANCE = 0.45    // lighter than this, dark text on the card stays easy to read

// The class's tint of the main colour: the same name always gets the same tint.
function shadeFor(title: string, mainColour: string): string {
  const main = parseColour(mainColour) ?? [136, 136, 136]   // unreadable setting: grey

  // A very dark main colour can't go as deep, or text on it gets hard to read.
  let deepest = DEEPEST
  while (deepest > LIGHTEST && luminance(tint(main, deepest)) < MIN_LUMINANCE) deepest -= 0.01

  const step = hash(title.trim().toLowerCase()) % SHADES
  const [r, g, b] = tint(main, LIGHTEST + ((deepest - LIGHTEST) * step) / (SHADES - 1))
  return `rgb(${r}, ${g}, ${b})`
}

// Mix a colour with white. share 0 = white, 1 = the colour itself.
function tint(colour: number[], share: number): number[] {
  return colour.map((c) => Math.round(255 - (255 - c) * share))
}

// How light a colour looks, from 0 (black) to 1 (white). The formula accessibility checks use.
function luminance(colour: number[]): number {
  const [r, g, b] = colour.map((c) => {
    const s = c / 255
    return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

// The colour itself if text in it is readable on `background` (4.5:1, the accessibility
// minimum), otherwise the colour darkened step by step until it is. For a light main
// colour used as text.
function readableText(colour: string, background: string): string {
  const fg = parseColour(colour)
  const bg = parseColour(background) ?? [255, 255, 255]
  if (!fg) return colour
  const contrast = (c: number[]) => (luminance(bg) + 0.05) / (luminance(c) + 0.05)
  let c = fg
  for (let k = 1; contrast(c) < 4.5 && k <= 20; k++) c = fg.map((v) => Math.round(v * (1 - k * 0.05)))
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`
}

// Framer gives colours as "#6b7a3a", "rgb(107, 122, 58)", "hsla(75, 36%, 35%, 0.5)" (when
// the colour has transparency), or, for a colour style, "var(--token-…, rgb(107, 122, 58))".
// Reads the first colour it finds.
function parseColour(value: string): number[] | null {
  const rgb = value.match(/rgba?\(\s*(\d+(?:\.\d+)?)[\s,]+(\d+(?:\.\d+)?)[\s,]+(\d+(?:\.\d+)?)/i)
  if (rgb) return [rgb[1], rgb[2], rgb[3]].map((c) => Math.round(Number(c)))

  const hsl = value.match(/hsla?\(\s*(-?\d+(?:\.\d+)?)(?:deg)?[\s,]+(\d+(?:\.\d+)?)%[\s,]+(\d+(?:\.\d+)?)%/i)
  if (hsl) return hslToRgb(Number(hsl[1]), Number(hsl[2]) / 100, Number(hsl[3]) / 100)

  const hex = value.match(/#([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})\b/i)
  if (!hex) return null
  const digits = hex[1].length === 3 ? [...hex[1]].map((c) => c + c).join("") : hex[1].slice(0, 6)
  return [0, 2, 4].map((i) => parseInt(digits.slice(i, i + 2), 16))
}

// Hue in degrees, saturation and lightness from 0 to 1, to [red, green, blue] from 0 to 255.
function hslToRgb(hue: number, s: number, l: number): number[] {
  const h = ((hue % 360) + 360) % 360
  const a = s * Math.min(l, 1 - l)
  const channel = (n: number) => {
    const k = (n + h / 30) % 12
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))))
  }
  return [channel(0), channel(8), channel(4)]
}

// Turns a name into a number, the same on every device (FNV-1a).
function hash(text: string): number {
  let h = 2166136261
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

// ── framer/calendar/MonthCalendar.tsx ───────────────────────────────────────

// MonthCalendar.tsx — the public calendar on a client's Framer site.
//
// Reads the classes and their places left from Supabase with the public key. View
// "Month" shows the current month as a grid; view "List" (set on the phone breakpoint)
// shows the upcoming classes. Tapping a class opens a panel to book it with a name and a
// phone number. The date, places and colour logic lives in month.ts, which has the
// tests. Nothing here is specific to one client: everything comes from the settings panel.
//
// Framer gets one file: `npm run build:framer` joins this and shared/month.ts into
// framer-build/MonthCalendar.tsx, which is what's saved to Framer.

const DAY_KEYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"] as const

// Everything the booking panel says, so a client can change the wording or the language.
const WORDS = {
  book: "Book",
  name: "Name",
  phone: "Phone",
  placesLeft: "{n} places left",
  lastPlace: "1 place left",
  full: "Full",
  booked: "You're in, {name}! See you {day} at {time}.",
  justFilled: "Sorry, this class just filled up.",
  alreadyBooked: "You're already booked for this class.",
  closed: "This class can't be booked any more.",
  invalidName: "Please enter your name.",
  invalidPhone: "Please enter a valid phone number.",
  failed: "Couldn't book right now. Please try again.",
  waitingList: "Join the waiting list on WhatsApp",
  waitingMessage: "Hi, I'd like to join the waiting list for {class} on {day} at {time}.",
  done: "Done",
  bookOnWhatsapp: "Book through WhatsApp",
  bookingMessage: "Hi, I'd like to book {class} on {day} at {time}.",
}
type Words = typeof WORDS

interface Props {
  supabaseUrl: string
  publicKey: string
  view: "month" | "list"
  days: Partial<Record<(typeof DAY_KEYS)[number], boolean>>
  language: string
  placesFrom: number
  whatsapp: string
  method: "website" | "whatsapp"
  mainColour: string
  textColour: string
  mutedColour: string
  lineColour: string
  panelColour: string
  buttonColour: string
  buttonTextColour: string
  titleFont: CSSProperties
  textFont: CSSProperties
  listTitle: string
  emptyMonthText: string
  emptyListText: string
  errorText: string
  words: Partial<Words>
  style?: CSSProperties
}

type Data = { timeZone: string; sessions: CalendarSession[] }
type State = { status: "loading" } | { status: "setup" } | { status: "error" } | ({ status: "ready" } & Data)

/**
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight auto
 */
export default function MonthCalendar(props: Props) {
  const { supabaseUrl, publicKey, view } = props
  const inEditor = useIsStaticRenderer()      // Framer's canvas: made-up classes, no network
  const [state, setState] = useState<State>({ status: "loading" })
  const [booking, setBooking] = useState<PlacedSession | null>(null)   // the class being booked

  useEffect(() => {
    if (inEditor) return
    if (!supabaseUrl || !publicKey) {
      setState({ status: "setup" })
      return
    }
    let stale = false
    setState({ status: "loading" })
    load(supabaseUrl, publicKey)
      .then((data) => { if (!stale) setState({ status: "ready", ...data }) })
      .catch(() => { if (!stale) setState({ status: "error" }) })
    return () => { stale = true }
  }, [inEditor, supabaseUrl, publicKey])

  // After an answer from the database, show the new number of places without reloading.
  function updatePlaces(id: string, placesLeft: number | null) {
    setState((s) => s.status !== "ready" ? s : {
      ...s,
      sessions: s.sessions.map((x) => (x.id === id ? { ...x, places_left: placesLeft } : x)),
    })
  }

  const language = safeLanguage(props.language)
  const data = inEditor ? sample() : state.status === "ready" ? state : null

  let body
  if (state.status === "setup" && !inEditor) body = <Note props={props}>Add the Supabase URL and public key in this component's settings.</Note>
  else if (state.status === "error" && !inEditor) body = <Note props={props}>{props.errorText}</Note>
  else if (!data) body = <Placeholder props={props} />
  else if (view === "list") body = <List data={data} props={props} language={language} onPick={setBooking} />
  else body = <MonthGrid data={data} props={props} language={language} onPick={setBooking} />

  const root: CSSProperties = {
    ...props.style,
    position: "relative",
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: 16,
    color: props.textColour,
    ...props.textFont,
  }
  return (
    <div style={root}>
      {body}
      {booking && (
        <BookingPanel
          session={booking}
          props={props}
          language={language}
          onClose={() => setBooking(null)}
          onPlaces={updatePlaces}
        />
      )}
    </div>
  )
}

// ------------------------------------------------------------------
//  Talking to Supabase
// ------------------------------------------------------------------

const COLUMNS = "id,title,starts_at,ends_at,location,details"

function api(url: string) {
  return `${url.replace(/\/+$/, "")}/rest/v1`
}

// The calendar's timezone first, because it decides which days to ask for; then the
// classes and their places left, both at once.
async function load(url: string, key: string): Promise<Data> {
  async function get(path: string) {
    const response = await fetch(`${api(url)}/${path}`, { headers: { apikey: key } })
    if (!response.ok) throw new Error(`Supabase answered ${response.status}`)
    return response.json()
  }
  const [info] = await get("sync_status?select=time_zone")
  if (!info?.time_zone) throw new Error("The calendar hasn't been synced yet")
  const { from, to } = fetchRange(new Date(), info.time_zone)
  const [rows, places] = await Promise.all([
    get(`sessions?select=${COLUMNS}&starts_at=gte.${from}&starts_at=lt.${to}&order=starts_at`),
    get(`rpc/places_left?p_from=${from}&p_to=${to}`),
  ])
  const left = new Map<string, number>()
  for (const p of places as { session_id: string; places_left: number }[]) left.set(p.session_id, p.places_left)
  const sessions: CalendarSession[] = (rows as Omit<CalendarSession, "places_left">[])
    .map((s) => ({ ...s, places_left: left.get(s.id) ?? null }))    // not listed = no limit
  return { timeZone: info.time_zone, sessions }
}

// One booking. The database checks everything and answers with a status:
// booked, full, already_booked, started, unavailable, invalid_name or invalid_phone.
async function book(url: string, key: string, session: string, name: string, phone: string) {
  const response = await fetch(`${api(url)}/rpc/book_session`, {
    method: "POST",
    headers: { apikey: key, "Content-Type": "application/json" },
    body: JSON.stringify({ p_session: session, p_name: name, p_phone: phone }),
  })
  if (!response.ok) throw new Error(`Supabase answered ${response.status}`)
  return (await response.json()) as { status: string; places_left?: number | null }
}

// A language the browser doesn't know (a typo in the settings) falls back to English.
function safeLanguage(language: string): string {
  try {
    new Intl.DateTimeFormat(language)
    return language
  } catch {
    return "en"
  }
}

// Made-up classes for Framer's canvas, so the calendar can be designed without data.
// Some are nearly full and some full, to show how those look.
function sample(): Data {
  const week: [string, number][] = [
    ["Morning Flow", 9], ["Strength", 18], ["Morning Flow", 9],
    ["Strength", 18], ["Evening Stretch", 19], ["Weekend Workshop", 10],
  ]
  const today = new Date()
  const sessions: CalendarSession[] = []
  for (let i = 0; i < 60; i++) {
    const day = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1 + i))
    const weekday = (day.getUTCDay() + 6) % 7
    if (weekday === 6) continue                                   // none on Sundays
    const [title, hour] = week[weekday]
    day.setUTCHours(hour)
    const start = day.toISOString()
    const places_left = i % 7 === 3 ? 0 : i % 5 === 1 ? 2 : null
    sessions.push({ id: start, title, starts_at: start, ends_at: start, location: null, details: { Host: "Alex" }, places_left })
  }
  return { timeZone: "UTC", sessions }
}

// ------------------------------------------------------------------
//  Month view
// ------------------------------------------------------------------

type Pick = (session: PlacedSession) => void

function MonthGrid({ data, props, language, onPick }: { data: Data; props: Props; language: string; onPick: Pick }) {
  const days = DAY_KEYS.flatMap((key, i) => ((props.days?.[key] ?? i < 6) ? [i] : []))   // default Monday–Saturday
  const month = buildMonth(data.sessions, { now: new Date(), timeZone: data.timeZone, days })
  const names = weekdayNames(language)
  const line = `1px solid ${props.lineColour}`
  const hasClasses = month.weeks.some((week) => week.some((d) => d.sessions.length > 0))

  const grid: CSSProperties = {
    display: "grid",
    gridTemplateColumns: `repeat(${month.weekdays.length}, minmax(0, 1fr))`,
    borderTop: line,
    borderLeft: line,
  }
  const header: CSSProperties = {
    padding: "8px",
    borderRight: line,
    borderBottom: line,
    color: props.mutedColour,
    fontSize: "0.8em",
    textTransform: "uppercase",
    letterSpacing: "0.05em",
  }

  return (
    <>
      <Title props={props}>{monthTitle(month.year, month.month, language)}</Title>
      {hasClasses ? (
        <div style={grid}>
          {month.weekdays.map((w) => <div key={`weekday-${w}`} style={header}>{names[w]}</div>)}
          {month.weeks.flat().map((d) => <DayCell key={d.key} day={d} props={props} onPick={onPick} />)}
        </div>
      ) : (
        <Note props={props}>{props.emptyMonthText}</Note>
      )}
    </>
  )
}

function DayCell({ day, props, onPick }: { day: Day; props: Props; onPick: Pick }) {
  const line = `1px solid ${props.lineColour}`
  const cell: CSSProperties = {
    minHeight: 110,
    minWidth: 0,
    padding: 8,
    display: "flex",
    flexDirection: "column",
    gap: 6,
    borderRight: line,
    borderBottom: line,
    background: day.isToday ? `color-mix(in srgb, ${props.mainColour} 10%, transparent)` : undefined,
  }
  if (!day.inMonth) return <div style={cell} />                  // before the 1st or after the last

  return (
    <div style={cell}>
      <div style={{ fontSize: "0.85em", fontWeight: day.isToday ? 700 : 500, color: day.isPast ? props.mutedColour : props.textColour }}>
        {day.date}
      </div>
      {day.sessions.map((s) => <ClassCard key={s.id} session={s} props={props} onPick={onPick} />)}
    </div>
  )
}

// ------------------------------------------------------------------
//  List view (phones)
// ------------------------------------------------------------------

function List({ data, props, language, onPick }: { data: Data; props: Props; language: string; onPick: Pick }) {
  const classes = upcoming(data.sessions, { now: new Date(), timeZone: data.timeZone })
  return (
    <>
      {props.listTitle && <Title props={props}>{props.listTitle}</Title>}
      {classes.length === 0 ? (
        <Note props={props}>{props.emptyListText}</Note>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {classes.map((s) => <ClassCard key={s.id} session={s} props={props} onPick={onPick} date={dayLabel(s.day, language)} />)}
        </div>
      )}
    </>
  )
}

// ------------------------------------------------------------------
//  A class: a card on its shade of the main colour
// ------------------------------------------------------------------

// In the grid it shows the time, name and details; in the list (`date` given) the date
// comes first and the name is bigger. It opens the booking panel when there's something
// to do there: a place to book, or the waiting list of a full class. With WhatsApp
// booking, the system doesn't know who booked, so it shows no places and opens the
// panel whenever there's a number to message.
function ClassCard({ session: s, props, onPick, date }: { session: PlacedSession; props: Props; onPick: Pick; date?: string }) {
  const words = wordsOf(props)
  const byWhatsapp = props.method === "whatsapp"
  const hasNumber = whatsappLink(props.whatsapp ?? "", "") !== null
  const note = byWhatsapp ? null : placesNote(s.places_left, props.placesFrom ?? 3)
  const details = Object.values(s.details).join(" · ")
  const canOpen = !s.past && (byWhatsapp ? hasNumber : note !== "full" || hasNumber)

  const style: CSSProperties = {
    background: shadeFor(s.title, props.mainColour),
    color: props.textColour,
    borderRadius: 8,
    padding: date ? "12px 14px" : "6px 8px",
    fontSize: "0.85em",
    overflowWrap: "anywhere",
    opacity: s.past ? 0.45 : 1,                                 // greyed once it has started
  }
  const content = (
    <>
      {date ? <div style={{ opacity: 0.75 }}>{date} · {s.time}</div> : <div style={{ fontWeight: 600 }}>{s.time}</div>}
      <div style={date ? { fontWeight: 600, fontSize: "1.15em" } : undefined}>{s.title}</div>
      {details && <div style={{ opacity: 0.75 }}>{details}</div>}
      {note !== null && !s.past && (
        <div style={{ fontWeight: 600 }}>
          {note === "full" ? words.full : note === 1 ? words.lastPlace : fillIn(words.placesLeft, { n: String(note) })}
        </div>
      )}
    </>
  )

  if (!canOpen) return <div style={style}>{content}</div>
  return (
    <button type="button" onClick={() => onPick(s)} style={{ ...buttonReset, ...style }}>
      {content}
    </button>
  )
}

// A <button> that looks like the card it wraps.
const buttonReset: CSSProperties = {
  display: "block",
  width: "100%",
  border: "none",
  margin: 0,
  textAlign: "left",
  cursor: "pointer",
  fontFamily: "inherit",
  fontWeight: "inherit",
  lineHeight: "inherit",
  letterSpacing: "inherit",
}

// ------------------------------------------------------------------
//  The booking panel
// ------------------------------------------------------------------

type Answer = string | null     // the status from book_session, "failed" if it couldn't be reached

function BookingPanel({ session: s, props, language, onClose, onPlaces }: {
  session: PlacedSession
  props: Props
  language: string
  onClose: () => void
  onPlaces: (id: string, placesLeft: number | null) => void
}) {
  const words = wordsOf(props)
  const [name, setName] = useState("")
  const [phone, setPhone] = useState("")
  const [sending, setSending] = useState(false)
  const [answer, setAnswer] = useState<Answer>(null)

  // Escape closes the panel
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose() }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onClose])

  const day = dayLabel(s.day, language)
  const values = { class: s.title, day, time: s.time, name: name.trim() }
  const waitingList = whatsappLink(props.whatsapp ?? "", fillIn(words.waitingMessage, values))
  const byWhatsapp = props.method === "whatsapp"
  const bookingLink = whatsappLink(props.whatsapp ?? "", fillIn(words.bookingMessage, values))
  const full = !byWhatsapp && (answer === "full" || (answer === null && s.places_left === 0))
  const note = byWhatsapp ? null : placesNote(s.places_left, props.placesFrom ?? 3)

  // Answers that end the booking; the others (a mistake in a field, no connection) keep the form.
  const final: Record<string, string> = {
    booked: fillIn(words.booked, values),
    full: words.justFilled,
    already_booked: words.alreadyBooked,
    started: words.closed,
    unavailable: words.closed,
  }
  const retry: Record<string, string> = {
    invalid_name: words.invalidName,
    invalid_phone: words.invalidPhone,
    failed: words.failed,
  }

  async function submit(e: FormEvent) {
    e.preventDefault()
    setSending(true)
    try {
      const result = await book(props.supabaseUrl, props.publicKey, s.id, name, phone)
      setAnswer(result.status)
      if (result.places_left !== undefined) onPlaces(s.id, result.places_left)
    } catch {
      setAnswer("failed")
    }
    setSending(false)
  }

  const overlay: CSSProperties = {
    position: "fixed",
    inset: 0,
    zIndex: 1000,
    background: "rgba(0, 0, 0, 0.4)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: 16,
  }
  const panel: CSSProperties = {
    ...props.textFont,
    position: "relative",
    width: "100%",
    maxWidth: 420,
    maxHeight: "100%",
    overflowY: "auto",
    boxSizing: "border-box",
    padding: 24,
    borderRadius: 16,
    background: props.panelColour,
    color: props.textColour,
    display: "flex",
    flexDirection: "column",
    gap: 16,
  }
  const input: CSSProperties = {
    font: "inherit",
    width: "100%",
    boxSizing: "border-box",
    padding: "12px 14px",
    marginTop: 6,
    borderRadius: 8,
    border: `1px solid ${props.lineColour}`,
    background: "transparent",
    color: props.textColour,
  }
  const button: CSSProperties = {
    font: "inherit",
    fontWeight: 600,
    padding: "12px 16px",
    borderRadius: 8,
    border: "none",
    cursor: "pointer",
    textAlign: "center",
    textDecoration: "none",
    background: props.buttonColour,
    color: props.buttonTextColour,
  }

  return createPortal(
    <div style={overlay} onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-label={s.title} style={panel} onClick={(e) => e.stopPropagation()}>
        <button type="button" aria-label="Close" onClick={onClose} style={{ ...buttonReset, position: "absolute", top: 12, right: 12, width: "auto", background: "none", fontSize: 22, color: props.mutedColour }}>
          ×
        </button>

        <div>
          <h3 style={{ margin: 0, paddingRight: 24, color: props.textColour, ...props.titleFont }}>{s.title}</h3>
          <div style={{ color: props.mutedColour, marginTop: 4 }}>{day} · {s.time}</div>
          {[Object.values(s.details).join(" · "), s.location].filter(Boolean).map((line) => (
            <div key={line} style={{ color: props.mutedColour }}>{line}</div>
          ))}
          {note !== null && answer === null && (
            <div style={{ fontWeight: 600, marginTop: 4 }}>
              {note === "full" ? words.full : note === 1 ? words.lastPlace : fillIn(words.placesLeft, { n: String(note) })}
            </div>
          )}
        </div>

        {byWhatsapp ? (
          bookingLink && <a href={bookingLink} target="_blank" rel="noopener noreferrer" style={button}>{words.bookOnWhatsapp}</a>
        ) : answer !== null && answer in final ? (
          <>
            <div role="status" style={{ fontWeight: 600 }}>{final[answer]}</div>
            {full && waitingList && <a href={waitingList} target="_blank" rel="noopener noreferrer" style={button}>{words.waitingList}</a>}
            <button type="button" onClick={onClose} style={{ ...button, background: "transparent", color: props.textColour, border: `1px solid ${props.lineColour}` }}>
              {words.done}
            </button>
          </>
        ) : full ? (
          waitingList && <a href={waitingList} target="_blank" rel="noopener noreferrer" style={button}>{words.waitingList}</a>
        ) : (
          <form onSubmit={submit} style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <label>
              {words.name}
              <input value={name} onChange={(e) => setName(e.target.value)} autoComplete="name" maxLength={80} required autoFocus style={input} />
            </label>
            <label>
              {words.phone}
              <input value={phone} onChange={(e) => setPhone(e.target.value)} type="tel" inputMode="tel" autoComplete="tel" required style={input} />
            </label>
            {answer !== null && answer in retry && <div role="alert" style={{ color: props.mutedColour }}>{retry[answer]}</div>}
            <button type="submit" disabled={sending} style={{ ...button, opacity: sending ? 0.6 : 1 }}>{words.book}</button>
          </form>
        )}
      </div>
    </div>,
    document.body,
  )
}

// ------------------------------------------------------------------
//  Small shared pieces
// ------------------------------------------------------------------

function wordsOf(props: Props): Words {
  return { ...WORDS, ...props.words }
}

function Title({ props, children }: { props: Props; children: string }) {
  return <h3 style={{ margin: 0, color: props.textColour, ...props.titleFont }}>{children}</h3>
}

function Note({ props, children }: { props: Props; children: string }) {
  return <p style={{ margin: 0, color: props.mutedColour }}>{children}</p>
}

// A soft placeholder while the classes load.
function Placeholder({ props }: { props: Props }) {
  const block: CSSProperties = { background: `color-mix(in srgb, ${props.mainColour} 6%, transparent)`, borderRadius: 8 }
  if (props.view === "list") {
    return <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>{[0, 1, 2].map((i) => <div key={i} style={{ ...block, height: 72 }} />)}</div>
  }
  return (
    <>
      <div style={{ ...block, height: 32, width: 220 }} />
      <div style={{ display: "grid", gridTemplateColumns: "repeat(6, minmax(0, 1fr))", gap: 4 }}>
        {Array.from({ length: 30 }, (_, i) => <div key={i} style={{ ...block, height: 110 }} />)}
      </div>
    </>
  )
}

